        await context.ExecuteAsync("insert into business_manufacturing.manufacturing_audit_event(tenant_id,id,entity_type,entity_id,action,actor_id,after_json,occurred_at) values($1,$2,'ProductionOrder',$3,'development_seed',$4,'{\"partialOutput\":60,\"materialIssued\":100,\"materialConsumed\":60,\"materialReturned\":40,\"forecastResidual\":400,\"grossRequirement\":1000,\"netRequirement\":1000}'::jsonb,$5) on conflict(tenant_id,id) do nothing", ct, tenant, SeedIds.Stable($"{tenant:D}:manufacturing:audit:partial"), order, actor, context.AsOf);
        return new ManufacturingSeedSummary(1, 2, 1, 2, 1, 1, 4, 1);
    }
}

public sealed record ManufacturingSeedSummary(int Plants, int Definitions, int ProductionOrders, int MaterialRequirements, int Outputs, int PlanningRuns, int PlannedSupplies, int CostFacts);
